/**
 * The surface's snapshot on the CDN — what `/v2/mobile/config` answers for the
 * page's key and platform, plus the products of the channels of its active
 * campaigns, regenerated by campaigns every ~90 s behind Cloudflare:
 *
 *   <snapshotBase><sha256(apiKey), hex, first 32>.<platform>.js
 *   → (window.__vioSnapshots ||= {})["<hash>.<platform>"] = { version, generatedAt, market, config, catalogs, products }
 *     and window.dispatchEvent(new CustomEvent("vio:snapshot", { detail: "<hash>.<platform>" }))
 *
 * The blob has no CORS headers, so it is loaded with a `<script async>`, not
 * fetched. With a fresh snapshot (generated under 10 minutes ago) the bootstrap
 * and the product cards need no request to the API: the SDK answers from it
 * and still asks the API for the bootstrap in the background. A load error, a
 * timeout or an old snapshot changes nothing — everything is asked as before.
 *
 * On its own on purpose (only `environments.ts`): the `./preload` entry starts
 * this before the SDK has even been downloaded, and the SDK picks up the same
 * load (the state lives on `globalThis`, so two copies of the SDK share it).
 *
 * Never throws.
 */

import { ENVIRONMENT_URLS, type Environment } from './environments.js'

/** Platforms campaigns writes a snapshot for (its `DOMAIN_PLATFORMS`). */
export const SNAPSHOT_PLATFORMS = ['web', 'custom-web', 'vev'] as const
export type SnapshotPlatform = (typeof SNAPSHOT_PLATFORMS)[number]

/** Older than this, a snapshot is not used (campaigns rewrites it every ~90 s). */
export const SNAPSHOT_MAX_AGE_MS = 10 * 60 * 1000
/** A snapshot that has not arrived by then is given up for this page. */
export const SNAPSHOT_TIMEOUT_MS = 4000
const SNAPSHOT_EVENT = 'vio:snapshot'

/** The channel a set of products came from, per campaign and sponsor. */
export interface SnapshotCatalog {
  campaignId: number
  sponsorId: number
  channelId: string
  productIds: number[]
}

/** A snapshot read and checked: everything the SDK answers from it. */
export interface SurfaceSnapshot {
  generatedAt: number
  market: { currency: string; shippingCountryCode: string }
  /** Exactly what `/v2/mobile/config` answers for the key and platform. */
  config: unknown
  catalogs: SnapshotCatalog[]
  /** The products (the shape of `Channel.GetProducts`), by id. */
  products: Map<number, unknown>
  /** Which channel each commerce key of the config sells with. */
  channelOfKey: Map<string, string>
  /** The channels each product appears in. */
  channelsOfProduct: Map<number, Set<string>>
}

interface LoadState {
  promise: Promise<SurfaceSnapshot | null>
  snapshot: SurfaceSnapshot | null
  settled: boolean
}

export interface SnapshotTarget {
  apiKey: string
  environment?: Environment
  platform?: string
}

function states(): Map<string, LoadState> {
  const g = globalThis as { __VIO_SNAPSHOT_STATES__?: Map<string, LoadState> }
  if (!(g.__VIO_SNAPSHOT_STATES__ instanceof Map)) g.__VIO_SNAPSHOT_STATES__ = new Map()
  return g.__VIO_SNAPSHOT_STATES__
}

function isSnapshotPlatform(value: unknown): value is SnapshotPlatform {
  return typeof value === 'string' && (SNAPSHOT_PLATFORMS as readonly string[]).includes(value)
}

/** `{ base, platform }` for a target, or null when no snapshot exists for it. */
function resolveTarget(target: SnapshotTarget): { key: string; base: string; platform: SnapshotPlatform } | null {
  const key = typeof target?.apiKey === 'string' ? target.apiKey.trim() : ''
  if (!key) return null
  const platform = target.platform ?? 'web'
  if (!isSnapshotPlatform(platform)) return null
  const env = target.environment ?? 'development'
  const base = ENVIRONMENT_URLS[env]?.snapshotBase
  if (!base) return null
  return { key, base, platform }
}

function stateKey(base: string, key: string, platform: string): string {
  return `${base}|${platform}|${key}`
}

async function sha256Hex(text: string): Promise<string | null> {
  try {
    const subtle = (globalThis as { crypto?: Crypto }).crypto?.subtle
    if (!subtle || typeof TextEncoder === 'undefined') return null
    const digest = await subtle.digest('SHA-256', new TextEncoder().encode(text))
    return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, '0')).join('')
  } catch {
    return null
  }
}

function loaded(): Record<string, unknown> | null {
  try {
    return typeof window !== 'undefined'
      ? ((window as unknown as { __vioSnapshots?: Record<string, unknown> }).__vioSnapshots ?? null)
      : null
  } catch {
    return null
  }
}

/** The snapshot script's data for `name`: already on the page, or once its event says so (null on error or timeout). */
function loadScript(src: string, name: string): Promise<unknown | null> {
  const ready = loaded()?.[name]
  if (ready) return Promise.resolve(ready)
  if (typeof document === 'undefined' || typeof window === 'undefined') return Promise.resolve(null)
  return new Promise((resolve) => {
    let done = false
    let script: HTMLScriptElement | null = null
    const finish = (value: unknown | null) => {
      if (done) return
      done = true
      clearTimeout(timer)
      try {
        window.removeEventListener(SNAPSHOT_EVENT, onEvent)
      } catch {
        /* gone */
      }
      resolve(value)
    }
    const onEvent = (e: Event) => {
      if ((e as CustomEvent).detail === name) finish(loaded()?.[name] ?? null)
    }
    const timer = setTimeout(() => {
      // Given up: the element goes, so a script that never answers does not hold the page's load event.
      try {
        script?.remove()
      } catch {
        /* already gone */
      }
      finish(loaded()?.[name] ?? null)
    }, SNAPSHOT_TIMEOUT_MS)
    try {
      window.addEventListener(SNAPSHOT_EVENT, onEvent)
      script = document.querySelector(`script[src="${src}"]`) as HTMLScriptElement | null
      if (!script) {
        script = document.createElement('script')
        script.async = true
        script.src = src
        ;(document.head || document.documentElement).appendChild(script)
      }
      script.addEventListener('error', () => finish(null))
      // A script that ran without the event: read what it left.
      script.addEventListener('load', () => setTimeout(() => finish(loaded()?.[name] ?? null), 0))
    } catch {
      finish(null)
    }
  })
}

function generatedAtOf(value: unknown): number {
  const n = typeof value === 'number' ? value : Date.parse(String(value ?? ''))
  return Number.isFinite(n) ? n : 0
}

function productIdOf(product: unknown): number | null {
  const raw = (product as { id?: unknown } | null)?.id
  const n = typeof raw === 'number' ? raw : typeof raw === 'string' && /^\d+$/.test(raw) ? Number(raw) : NaN
  return Number.isSafeInteger(n) && n > 0 ? n : null
}

/** The commerce keys of the config's sponsor blocks (top level and every campaign) and their channels. */
function channelsOfKeys(config: unknown): Map<string, string> {
  const out = new Map<string, string>()
  const add = (sponsor: unknown) => {
    const commerce = (sponsor as { commerce?: { apiKey?: unknown; channelId?: unknown } } | null)?.commerce
    const key = commerce?.apiKey
    const channel = commerce?.channelId
    if (typeof key === 'string' && key && channel != null && String(channel) !== '') out.set(key, String(channel))
  }
  const blocks = (holder: unknown) => {
    const h = holder as { primarySponsor?: unknown; secondarySponsors?: unknown } | null
    if (!h || typeof h !== 'object') return
    add(h.primarySponsor)
    if (Array.isArray(h.secondarySponsors)) h.secondarySponsors.forEach(add)
  }
  blocks(config)
  const campaigns = (config as { campaigns?: unknown } | null)?.campaigns
  if (Array.isArray(campaigns)) campaigns.forEach(blocks)
  return out
}

/** A snapshot document read and checked, or null when it is not one this SDK understands. */
export function readSnapshot(json: unknown): SurfaceSnapshot | null {
  if (!json || typeof json !== 'object') return null
  const doc = json as {
    version?: unknown
    generatedAt?: unknown
    market?: { currency?: unknown; shippingCountryCode?: unknown }
    config?: unknown
    catalogs?: unknown
    products?: unknown
  }
  if (doc.version !== 1) return null
  const config = doc.config && typeof doc.config === 'object' ? doc.config : null
  if (!config) return null
  const products = new Map<number, unknown>()
  if (Array.isArray(doc.products)) {
    for (const p of doc.products) {
      const id = productIdOf(p)
      if (id !== null) products.set(id, p)
    }
  }
  const catalogs: SnapshotCatalog[] = []
  const channelsOfProduct = new Map<number, Set<string>>()
  if (Array.isArray(doc.catalogs)) {
    for (const c of doc.catalogs as Array<Partial<SnapshotCatalog> | null>) {
      if (!c || typeof c !== 'object' || c.channelId == null || !Array.isArray(c.productIds)) continue
      const channelId = String(c.channelId)
      const ids = c.productIds.map(Number).filter((n) => Number.isSafeInteger(n) && n > 0)
      catalogs.push({ campaignId: Number(c.campaignId), sponsorId: Number(c.sponsorId), channelId, productIds: ids })
      for (const id of ids) {
        const set = channelsOfProduct.get(id) ?? new Set<string>()
        set.add(channelId)
        channelsOfProduct.set(id, set)
      }
    }
  }
  return {
    generatedAt: generatedAtOf(doc.generatedAt),
    market: {
      currency: String(doc.market?.currency ?? '').toUpperCase(),
      shippingCountryCode: String(doc.market?.shippingCountryCode ?? '').toUpperCase(),
    },
    config,
    catalogs,
    products,
    channelOfKey: channelsOfKeys(config),
    channelsOfProduct,
  }
}

/**
 * The address of a target's snapshot script — for a host that renders its
 * pages on a server and wants the snapshot to start with the HTML, not after
 * its own JavaScript:
 *
 *   <link rel="preconnect" href="https://container.vio.live">
 *   <script async src="${await snapshotUrl({ apiKey, environment: 'production' })}"></script>
 *
 * The SDK (and `preloadVio`) pick up a script tag with this address that is
 * already on the page instead of adding their own. Works in a browser and in
 * Node 20+ (it needs `crypto.subtle`); null when there is no snapshot for the
 * target or the name cannot be computed.
 */
export async function snapshotUrl(target: SnapshotTarget): Promise<string | null> {
  try {
    const t = resolveTarget(target)
    if (!t) return null
    const hash = await sha256Hex(t.key)
    return hash ? `${t.base}${hash.slice(0, 32)}.${t.platform}.js` : null
  } catch {
    return null
  }
}

/** Generated under `SNAPSHOT_MAX_AGE_MS` ago (a clock a little ahead is fine). */
export function isFresh(snapshot: SurfaceSnapshot | null, now = Date.now()): snapshot is SurfaceSnapshot {
  return !!snapshot && snapshot.generatedAt > 0 && now - snapshot.generatedAt < SNAPSHOT_MAX_AGE_MS
}

/**
 * Start loading the snapshot of a key, environment and platform (once per
 * page) and return it — null when there is none for that platform, the
 * browser cannot compute the name, it failed, timed out or is old.
 */
export function startSnapshot(target: SnapshotTarget): Promise<SurfaceSnapshot | null> {
  try {
    const t = resolveTarget(target)
    if (!t || typeof window === 'undefined') return Promise.resolve(null)
    const id = stateKey(t.base, t.key, t.platform)
    const known = states().get(id)
    if (known) return known.promise
    const state: LoadState = { promise: Promise.resolve(null), snapshot: null, settled: false }
    state.promise = (async () => {
      try {
        const hash = await sha256Hex(t.key)
        if (!hash) return null
        const name = `${hash.slice(0, 32)}.${t.platform}`
        const snapshot = readSnapshot(await loadScript(`${t.base}${name}.js`, name))
        if (!isFresh(snapshot)) return null
        state.snapshot = snapshot
        return snapshot
      } catch {
        return null
      } finally {
        state.settled = true
      }
    })()
    states().set(id, state)
    return state.promise
  } catch {
    return Promise.resolve(null)
  }
}

/**
 * The snapshot of a target as things stand: `pending` while it loads, `ready`
 * with it when it arrived and is still fresh, `none` otherwise (never started,
 * failed, timed out or old).
 */
export function snapshotState(
  target: SnapshotTarget,
): { status: 'pending'; promise: Promise<SurfaceSnapshot | null> } | { status: 'ready'; snapshot: SurfaceSnapshot } | { status: 'none' } {
  try {
    const t = resolveTarget(target)
    if (!t) return { status: 'none' }
    const state = states().get(stateKey(t.base, t.key, t.platform))
    if (!state) return { status: 'none' }
    if (!state.settled) return { status: 'pending', promise: state.promise }
    return isFresh(state.snapshot) ? { status: 'ready', snapshot: state.snapshot } : { status: 'none' }
  } catch {
    return { status: 'none' }
  }
}

export interface SnapshotProductQuery {
  /** The commerce key of the channel asking (the CommerceClient's). */
  commerceKey: string
  productIds: number[]
  currency: string
  shippingCountryCode: string
  imageSize: string
  useCache: boolean
}

/**
 * The products of `query` from the snapshot, in the order asked — or null
 * when the snapshot cannot answer for all of them exactly as the API would:
 * another market or image size, a fresh read asked for (`useCache: false`), a
 * key the snapshot does not know, an id not in that key's channel, or an id
 * that appears in more than one channel (its copy there may differ).
 */
export function snapshotProducts(snapshot: SurfaceSnapshot, query: SnapshotProductQuery): unknown[] | null {
  try {
    if (!query.productIds.length || query.useCache === false) return null
    if (query.imageSize !== 'large') return null
    if (String(query.currency).toUpperCase() !== snapshot.market.currency) return null
    if (String(query.shippingCountryCode).toUpperCase() !== snapshot.market.shippingCountryCode) return null
    const channel = snapshot.channelOfKey.get(query.commerceKey)
    if (channel === undefined) return null
    const out: unknown[] = []
    for (const id of query.productIds) {
      const channels = snapshot.channelsOfProduct.get(id)
      if (!channels || channels.size !== 1 || !channels.has(channel)) return null
      const product = snapshot.products.get(id)
      // A snapshot from before campaigns asked the full product (sku, tags,
      // categories…): the API answers instead, never a product with less.
      if (!product || typeof product !== 'object' || !('sku' in product)) return null
      out.push(product)
    }
    return out
  } catch {
    return null
  }
}

/** Tests only: forget every load of this page. */
export function resetSnapshots(): void {
  states().clear()
}
